from psyclone.transformations import (
    Dynamo0p3RedundantComputationTrans,
    Dynamo0p3AsyncHaloExchangeTrans,
    Dynamo0p3ColourTrans,
    InlineTrans,
    OMPParallelLoopTrans,
    TransformationError
)
from psyclone.core import PSycloneError

# Boolean variables to control transformations
APPLY_REDUNDANT_COMP = True
APPLY_ASYNC_HEX = True
APPLY_OMP_COLOUR = True
APPLY_INTRINSIC_INLINE = True

def apply_transformations(psy):
    """
    Applies a series of transformations to all invokes in the given psy object.
    Transformations include redundant computation, asynchronous halo exchanges,
    OpenMP colouring, and intrinsic inlining, controlled by boolean variables.
    Handles TransformationErrors and returns the transformed psy object.
    """
    rc_trans = Dynamo0p3RedundantComputationTrans()
    async_hex_trans = Dynamo0p3AsyncHaloExchangeTrans()
    colour_trans = Dynamo0p3ColourTrans()
    omp_parallel_trans = OMPParallelLoopTrans()
    inline_trans = InlineTrans()

    for invoke in psy.invokes.invoke_list:
        schedule = invoke.schedule
        try:
            if APPLY_REDUNDANT_COMP:
                rc_trans.apply(schedule.children[0])
            if APPLY_ASYNC_HEX:
                for node in schedule.walk('DynHaloExchange'):
                    async_hex_trans.apply(node)
            if APPLY_OMP_COLOUR:
                for loop in schedule.loops():
                    if loop.loop_type == "colour":
                        colour_trans.apply(loop)
                for loop in schedule.loops():
                    if loop.loop_type == "coloured":
                        omp_parallel_trans.apply(loop)
            if APPLY_INTRINSIC_INLINE:
                for kern in schedule.walk('CodedKern'):
                    inline_trans.apply(kern)
        except TransformationError as err:
            print(f"TransformationError in invoke '{invoke.name}': {err}")
        except PSycloneError as err:
            print(f"PSycloneError in invoke '{invoke.name}': {err}")
    return psy
